components-notes-badges--pools.snippet:
const Pools = () => (
  <div className="flex gap-2">
    {pools.map((pool) => (
      <PoolBadge key={pool} pool={pool} />
    ))}
  </div>
);

components-notes-badges--statuses.snippet:
const Statuses = () => (
  <div className="flex gap-2">
    <StatusBadge status="unspent" />
    <StatusBadge status="spent" />
    <StatusBadge status="pending" />
  </div>
);

components-notes-badges--dots.snippet:
const Dots = () => (
  <div className="flex items-center gap-3">
    {pools.map((pool) => (
      <PoolDot key={pool} pool={pool} />
    ))}
  </div>
);
